import json
from pathlib import Path

payload = json.loads(r'''{"output_path": "/home/icsl/sothoth/13-secflow-service/image_build/secflow-app-firmware-unpacker/unpacked-demo2-skill-rerun-unified/S6730_V200R024C00SPC500.cc/output"}''')
output = Path(payload['output_path'])
removed_files = []
removed_dirs = []
for path in sorted(output.rglob('*')):
    try:
        if path.is_file() and path.stat().st_size == 0:
            path.unlink()
            removed_files.append(str(path.relative_to(output)))
    except OSError:
        continue
for path in sorted([p for p in output.rglob('*') if p.is_dir()], reverse=True):
    try:
        if any(path.iterdir()):
            continue
        path.rmdir()
        removed_dirs.append(str(path.relative_to(output)))
    except OSError:
        continue
print(json.dumps({'removed_files': removed_files, 'removed_dirs': removed_dirs}, ensure_ascii=False))
